267: /// Does not change what is provable (conservativity).
268: pub fn optimize(proof: &[JustifiedStatement]) -> Vec<JustifiedStatement> {
269:     let mut result: Vec<JustifiedStatement> = Vec::new();
270:     let mut seen_content: std::collections::HashSet<String> = std::collections::HashSet::new();
271: 
272:     for js in proof {
273:         // Only retain verified statements.
274:         if !verify(js) {
275:             continue;
276:         }
277:         // Deduplicate by content.
278:         if seen_content.insert(js.statement.content.clone()) {
279:             result.push(js.clone());
280:         }
281:     }
