20: void void_batch_hamming_dist_neon(
21:     const uint8_t* query, 
22:     const uint8_t* batch, 
23:     uint64_t* distances, 
24:     size_t count, 
25:     size_t len
26: ) {
27:     for (size_t i = 0; i < count; i++) {
28:         const uint8_t* target = batch + (i * len);
29:         uint64_t total_dist = 0;
30:         size_t j = 0;
31:         
32:         for (; j <= len - 16; j += 16) {
33:             uint8x16_t vq = vld1q_u8(query + j);
34:             uint8x16_t vt = vld1q_u8(target + j);
35:             uint8x16_t vxor = veorq_u8(vq, vt);
36:             uint8x16_t vcnt = vcntq_u8(vxor);
37:             total_dist += vaddlvq_u8(vcnt);
38:         }
39:         
40:         for (; j < len; j++) {
41:             total_dist += __builtin_popcount(query[j] ^ target[j]);
42:         }
43:         distances[i] = total_dist;

